    if (!(+f.kg > 0 && +f.kg <= 33 * 1200)) return T('Укажите массу, кг', 'Masse in kg angeben', 'Enter the weight in kg', 'Массаны кг көрсетіңіз');
    if (f.h !== '' && f.h != null && !(+f.h >= 20 && +f.h <= 300)) return T('Высота: 20–300 см', 'Höhe: 20–300 cm', 'Height: 20–300 cm', 'Биіктік: 20–300 см');
